def stitch_broken_tables(df):
    import pandas as pd
    if df is None or getattr(df, "empty", True) or "raw_chunk" not in df.columns:
        return df
    def broken(text):
        t = str(text or "")
        low = t.lower()
        s = t.lstrip().lower()
        if low.count("<table") > low.count("</table"):
            return True
        return s.startswith(("td>", "/td>", "tr>", "/tr>", "</td", "</tr", "th>", "/th>"))
    out = []
    buf = None
    for rec in df.to_dict(orient="records"):
        text = str(rec.get("raw_chunk") or "")
        if buf is None:
            buf = rec
            continue
        prev = str(buf.get("raw_chunk") or "")
        same = buf.get("source") == rec.get("source")
        if same and (broken(prev) or broken(text)) and (len(prev) + len(text) < 12000):
            merged = dict(buf)
            merged["raw_chunk"] = prev + "\n" + text
            buf = merged
        else:
            out.append(buf)
            buf = rec
    if buf is not None:
        out.append(buf)
    return pd.DataFrame(out)

def keep_body_chunks(df):
    import re
    if df is None or getattr(df, "empty", True) or "cleaned_chunk" not in df.columns:
        return df
    def keep(text):
        t = str(text or "").strip()
        if len(t) < 80:
            return False
        cites = len(re.findall(r"\[\d+\]", t))
        if cites >= 4 and len(t) < 700:
            return False
        if t.lstrip().startswith(("参考文献",)) and cites >= 2:
            return False
        if t.count("$^{") >= 6 and len(t) < 450:
            return False
        if re.match(r"^[\s,A-Za-z\-\.]+\$\{\^", t) and len(t) < 350:
            return False
        return True
    return df.loc[df["cleaned_chunk"].map(keep)].reset_index(drop=True)

def refine_qa_pairs(df):
    import re
    if df is None or getattr(df, "empty", True):
        return df
    if "generated_question" not in df.columns or "generated_answer" not in df.columns:
        return df
    out = df.copy()

    def norm(s):
        s = str(s or "")
        s = re.sub(r"\s+", "", s)
        for a, b in (("（", "("), ("）", ")"), ("，", ","), ("。", ""), ("、", ""), ("：", ":"), ("；", ";")):
            s = s.replace(a, b)
        return s.lower()

    def abstain(ans):
        a = str(ans or "")
        return any(x in a for x in ("未提及", "未给出", "原文没有", "无法从原文", "不知道", "原文未"))

    def grounded(row):
        chunk = str(row.get("cleaned_chunk") or row.get("kb_text") or "")
        question = str(row.get("generated_question") or "")
        ans = str(row.get("generated_answer") or "")
        if not ans.strip() or abstain(ans):
            return False
        nchunk, nans = norm(chunk), norm(ans)
        if len(nans) >= 2 and nans in nchunk:
            return True
        nums = re.findall(r"\d+(?:\.\d+)?", ans)
        if nums and not all(n in chunk for n in nums):
            return False
        latin = re.findall(r"[A-Za-z][A-Za-z0-9\-]{1,}", ans)
        cl = chunk.lower()
        if latin and all(tok.lower() in cl for tok in latin):
            return True
        q_latin = re.findall(r"[A-Za-z][A-Za-z0-9\-]{1,}", question)
        ascii_ratio = sum(ch.isascii() and not ch.isspace() for ch in chunk) / float(max(len(chunk), 1))
        if ascii_ratio > 0.65 and any(tok.lower() in cl for tok in (latin + q_latin)):
            return True
        hans = re.findall(r"[\u4e00-\u9fff]+", ans)
        grams = []
        for h in hans:
            if len(h) == 1:
                grams.append(h)
            else:
                grams.extend(h[i:i + 2] for i in range(len(h) - 1))
        if grams:
            hit = sum(1 for g in grams if g in chunk)
            return (hit / float(len(grams))) >= 0.5
        return bool(nums)

    out = out.loc[out.apply(grounded, axis=1)].copy()
    if getattr(out, "empty", True):
        return out.reset_index(drop=True)
    if "source" in out.columns:
        src = out["source"].fillna("").astype(str)
    else:
        src = out.index.astype(str)
    qkey = out["generated_question"].fillna("").astype(str).map(norm)
    key = src + chr(31) + qkey
    return out.loc[~key.duplicated(keep="first")].reset_index(drop=True)

def wrap_qa_pairs(df):
    import pandas as pd
    if df is None:
        return df
    out = df.copy()
    for col in ("generated_question", "generated_answer"):
        if col not in out.columns:
            out[col] = pd.Series(dtype="object")
    if getattr(out, "empty", True):
        out["QA_pairs"] = pd.Series(dtype="object")
        return out
    out["QA_pairs"] = [[{"question": str(q), "answer": str(a), "type": "factual"}] for q, a in zip(out["generated_question"].fillna(""), out["generated_answer"].fillna(""))]
    return out
